args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-29-omics-library-next/marker');S<-file.path(P,'biofigure');D<-file.path(P,'results/plot_data');source(file.path(S,'scripts/figure_style.R'))
suppressPackageStartupMessages({library(ComplexHeatmap);library(circlize);library(grid);library(ggplot2);library(ggplotify)})
q<-jsonlite::fromJSON(file.path(W,'input-qc.json'));font<-bf_font('Arial');bf_complexheatmap_font(font)
meta<-read.csv(file.path(D,q$plot_data_files[3]),check.names=FALSE);feat<-read.csv(file.path(D,q$plot_data_files[4]),check.names=FALSE);z<-read.csv(file.path(D,q$plot_data_files[2]),check.names=FALSE,row.names=1);mat<-as.matrix(z);lineage<-meta$lineage;lnames<-unique(lineage);cols<-unlist(q$palette);labelcols<-unlist(q$marker_label_palette)
col_fun<-colorRamp2(c(-4,0,4),c('#6250A3','#FAFAF8','#D45A31'))
blocks<-split(seq_len(ncol(mat)),factor(lineage,levels=lnames))
ha<-HeatmapAnnotation(`Cell lineage`=anno_block(align_to=blocks,panel_fun=function(index,nm){grid.rect(gp=gpar(fill=cols[nm],col='#FFFFFF',lwd=.5));grid.text(nm,gp=gpar(fontfamily='Arial',fontsize=7,fontface='bold',col='white'))},height=unit(3,'mm'),show_name=TRUE),`Cell type`=anno_simple(meta$cell_type,col=unlist(q$cell_colors),border=FALSE,height=unit(2,'mm')),annotation_name_gp=gpar(fontfamily='Arial',fontsize=7),show_legend=FALSE,gap=unit(.6,'mm'))
at<-which(nzchar(feat$marker_label));ra<-rowAnnotation(markers=anno_mark(at=at,labels=feat$marker_label[at],labels_gp=gpar(fontfamily='Arial',fontsize=7,col=labelcols[feat$lineage[at]]),link_gp=gpar(col='#62676C',lwd=.45),padding=unit(.7,'mm'),link_width=unit(2,'mm')),show_annotation_name=FALSE,width=unit(17,'mm'))
ht<-Heatmap(mat,name='rowz',col=col_fun,cluster_rows=TRUE,clustering_distance_rows='euclidean',clustering_method_rows='single',cluster_columns=FALSE,show_row_names=FALSE,row_dend_width=unit(7,'mm'),row_dend_gp=gpar(col='#4C5359',lwd=.35),column_names_gp=gpar(fontfamily='Arial',fontsize=7),column_names_rot=90,column_names_max_height=unit(38,'mm'),top_annotation=ha,right_annotation=ra,width=unit(139,'mm'),height=unit(100,'mm'),use_raster=FALSE,rect_gp=gpar(col=NA),border=FALSE,heatmap_legend_param=list(title='Row Z-score',title_gp=gpar(fontfamily='Arial',fontsize=7),labels_gp=gpar(fontfamily='Arial',fontsize=7),at=c(-4,-2,0,2,4),direction='horizontal',legend_width=unit(30,'mm'),title_position='lefttop',border=NA))
# Exploratory current-size layout; formal export is gated separately.
ragg::agg_png(file.path(W,'layout-preflight.png'),width=183,height=158,units='mm',res=200,background='white');drawn<-draw(ht,heatmap_legend_side='bottom',padding=unit(c(2,3,2,2),'mm'),merge_legends=TRUE)
saveRDS(drawn,file.path(W,'drawn-heatmap.rds'));metrics<-bf_complexheatmap_cell_metrics(drawn,'rowz',cell_mode='dense-overview');jsonlite::write_json(metrics,file.path(W,'native-cell-metrics.json'),auto_unbox=TRUE,pretty=TRUE,digits=NA)
write.csv(data.frame(display_position=seq_len(nrow(mat)),feature_id=rownames(mat)[row_order(drawn)]),file.path(D,'repro046_marker_heatmap_20261029_row_order.csv'),row.names=FALSE)
g<-grid.grab(wrap=TRUE);dev.off();labels<-character();sizes<-numeric();fix<-function(x){if(inherits(x,'text')){x$gp$fontfamily<-'Arial';if(is.null(x$gp$fontsize))x$gp$fontsize<-7;x$gp$cex<-1;labels<<-c(labels,as.character(x$label));sizes<<-c(sizes,x$gp$fontsize)};if(length(x$grobs))x$grobs<-lapply(x$grobs,fix);if(length(x$children))x$children<-do.call(gList,lapply(x$children,fix));x};g<-fix(g);saveRDS(g,file.path(W,'composed-vector-grob.rds'));wrapped<-as.ggplot(g)+theme(text=element_text(family='Arial',size=7),plot.margin=margin(0,0,0,0));saveRDS(wrapped,file.path(W,'render-object.rds'));saveRDS(ht,file.path(W,'native-heatmap.rds'))
jsonlite::write_json(list(labels=unique(labels[nzchar(labels)]),point_sizes=sort(unique(sizes))),file.path(W,'text-manifest.json'),auto_unbox=TRUE,pretty=TRUE)
